package orchestrator

import (
	"testing"
	"time"
)

// ep is a test-episode builder: packable by default, never packaged, no
// cooldown — the common case each table case then overrides.
func ep(id string) Episode {
	return Episode{ItemID: id, Packable: true}
}

// serial is a test-serial builder: streams enabled, canonical episode order.
func serial(lib int64, episodes ...Episode) Serial {
	return Serial{LibraryID: lib, StreamsEnabled: true, Episodes: episodes}
}

var (
	// testNow is the frontier's evaluation clock; coolPast is a deadline in
	// the past (cooldown elapsed — eligible), coolFuture one still running.
	testNow    = time.Date(2026, 10, 9, 12, 0, 0, 0, time.UTC)
	coolPast   = testNow.Add(-time.Hour)
	coolFuture = testNow.Add(time.Hour)
)

// TestFrontier is the acceptance test for spec "Watch-driven packaging
// frontier" (all three scenarios) plus the cooldown/packaged/eligibility
// negatives. Each case feeds Frontier one serial-shaped snapshot and asserts
// the exact job set (item ids in order).
func TestFrontier(t *testing.T) {
	cases := []struct {
		name    string
		in      FrontierIn
		wantIDs []string // empty asserts NO jobs
	}{
		// Scenario 1: watching episode K fronts exactly K+1.
		{
			name: "watched_episode_fronts_next_only",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), ep("e2"), ep("e3"))},
				Watched: map[string]bool{"e2": true},
				Now:     testNow,
			},
			wantIDs: []string{"e3"},
		},
		{
			name: "last_watched_wins_over_gap",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), ep("e2"), ep("e3"), ep("e4"))},
				Watched: map[string]bool{"e1": true, "e3": true},
				Now:     testNow,
			},
			wantIDs: []string{"e4"},
		},
		{
			name: "fully_watched_serial_fronts_nothing",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), ep("e2"))},
				Watched: map[string]bool{"e1": true, "e2": true},
				Now:     testNow,
			},
		},

		// Scenario 2a: fresh serial fronts its eager pilot E1.
		{
			name: "fresh_serial_fronts_pilot",
			in: FrontierIn{
				Serials: []Serial{serial(2, ep("p1"), ep("p2"))},
				Watched: map[string]bool{},
				Now:     testNow,
			},
			wantIDs: []string{"p1"},
		},
		// Scenario 2b: movies wait for play — they are absent from the input
		// by construction, so even watched movie ids never mint a job.
		{
			name:    "watched_movies_alone_front_nothing",
			in:      FrontierIn{Serials: nil, Watched: map[string]bool{"movie-a": true, "movie-b": true}, Now: testNow},
			wantIDs: nil,
		},

		// Scenario 3: the streams-disabled library gate skips the serial.
		{
			name: "streams_disabled_library_skipped",
			in: FrontierIn{
				Serials: []Serial{{LibraryID: 3, StreamsEnabled: false, Episodes: []Episode{ep("d1"), ep("d2")}}},
				Watched: map[string]bool{"d1": true},
				Now:     testNow,
			},
		},

		// Eligibility negatives on the candidate.
		{
			name: "already_packaged_candidate_not_reenqueued",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), Episode{ItemID: "e2", Packable: true, Packaged: true})},
				Watched: map[string]bool{"e1": true},
				Now:     testNow,
			},
		},
		{
			name: "candidate_inside_failure_cooldown_not_reenqueued",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), Episode{ItemID: "e2", Packable: true, CoolUntil: coolFuture})},
				Watched: map[string]bool{"e1": true},
				Now:     testNow,
			},
		},
		{
			name: "candidate_cooldown_elapsed_is_enqueued",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), Episode{ItemID: "e2", Packable: true, CoolUntil: coolPast})},
				Watched: map[string]bool{"e1": true},
				Now:     testNow,
			},
			wantIDs: []string{"e2"},
		},
		{
			name: "unpackable_classification_candidate_skipped",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), Episode{ItemID: "e2", Packable: false})},
				Watched: map[string]bool{"e1": true},
				Now:     testNow,
			},
		},
		{
			name: "empty_serial_fronts_nothing",
			in: FrontierIn{
				Serials: []Serial{serial(1)},
				Watched: map[string]bool{},
				Now:     testNow,
			},
		},
		{
			name: "two_serials_front_independently",
			in: FrontierIn{
				Serials: []Serial{
					serial(1, ep("a1"), ep("a2")),
					serial(1, ep("b1"), ep("b2")),
				},
				Watched: map[string]bool{"a2": true, "b1": true},
				Now:     testNow,
			},
			wantIDs: []string{"b2"},
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			got := Frontier(tc.in)
			ids := make([]string, len(got))
			for i, j := range got {
				ids[i] = j.ItemID
			}
			if len(ids) != len(tc.wantIDs) {
				t.Fatalf("Frontier() job ids = %v, want %v", ids, tc.wantIDs)
			}
			for i := range ids {
				if ids[i] != tc.wantIDs[i] {
					t.Fatalf("Frontier() job ids = %v, want %v", ids, tc.wantIDs)
				}
			}
		})
	}
}

// TestFrontierJobShape pins the attribution fields (library + reason) that
// the operator log and the enqueue site consume.
func TestFrontierJobShape(t *testing.T) {
	in := FrontierIn{
		Serials: []Serial{serial(7, ep("w1"), ep("w2"))},
		Watched: map[string]bool{"w1": true},
		Now:     testNow,
	}
	got := Frontier(in)
	if len(got) != 1 {
		t.Fatalf("Frontier() = %d jobs, want 1", len(got))
	}
	if got[0].LibraryID != 7 || got[0].Reason != reasonNext {
		t.Fatalf("Frontier() job = %+v, want library 7 reason %q", got[0], reasonNext)
	}

	pilot := Frontier(FrontierIn{Serials: in.Serials, Watched: map[string]bool{}, Now: testNow})
	if len(pilot) != 1 || pilot[0].ItemID != "w1" || pilot[0].Reason != reasonPilot {
		t.Fatalf("Frontier() pilot = %+v, want w1/%q", pilot, reasonPilot)
	}
}

// TestOnPlay is the pack-on-play acceptance table (movies pack on play,
// never pre-warmed): the same eligibility rule the sweep enforces, applied
// at the play that asks for it.
func TestOnPlay(t *testing.T) {
	cases := []struct {
		name string
		e    Episode
		want bool
	}{
		{"packable_unpackaged_no_cooldown_enqueues", ep("m1"), true},
		{"already_packaged_no_enqueue", Episode{ItemID: "m1", Packable: true, Packaged: true}, false},
		{"inside_cooldown_no_enqueue", Episode{ItemID: "m1", Packable: true, CoolUntil: coolFuture}, false},
		{"elapsed_cooldown_enqueues", Episode{ItemID: "m1", Packable: true, CoolUntil: coolPast}, true},
		{"unpackable_classification_no_enqueue", Episode{ItemID: "m1", Packable: false}, false},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			if got := OnPlay(tc.e, testNow); got != tc.want {
				t.Fatalf("OnPlay(%+v) = %v, want %v", tc.e, got, tc.want)
			}
		})
	}
}
